import pathlib, re, sys

root = pathlib.Path('experimentos')
new = {}
for e in ['control', 'h1', 'h2', 'h3', 'sampling_1']:
    for d in ['hipotesis.md', 'diseno.md']:
        new[f'{e}/{d}'] = (root / e / 'docs' / d).read_text()


def norm(s):
    return re.sub(r'\s+', ' ', s).strip()


newn = {k: norm(v) for k, v in new.items()}
for old in sys.argv[1:]:
    txt = pathlib.Path(old).read_text()
    chunks = [c for c in re.split(r'\n(?=\s*[-|#]|\s*\n)', txt) if len(norm(c)) > 25]
    print('=====', old, len(chunks))
    for c in chunks:
        n = norm(c)
        hits = [k for k, v in newn.items() if n in v]
        if len(hits) != 1:
            print(len(hits), hits, '|', n[:140])
